  "ai.res.tryon.desc": { zh: "服装、饰品、箱包等品类，上传商品图即可生成真人上身效果。由第三方服务「易点」提供，按张计费，独立结算。", en: "For apparel, accessories, bags and more — upload a product photo to generate on-model try-on images. Powered by third-party service Yidian, billed per image and settled separately." },
