  "feeMgmt.note": { zh: "科目由系统按用户预置并随新用户自动初始化；停用后不再接收新同步数据，历史数据保留参与利润计算。科目代码保持稳定，平台字段映射依赖代码。", en: "Accounts are seeded per user automatically. Deactivated accounts stop receiving new synced data; historical records remain in profit calculation. Keep codes stable — platform field mappings depend on them." },
