  "profit.order.formula": { zh: "净利 = 收入 − Σ平台费用（同币种） − 商品成本；无费用记录的订单净利 = 收入 − 成本（估算）。", en: "Net = revenue − Σ platform fees (same currency) − product cost; orders without fee records fall back to revenue − cost (estimated)." },
