  "profit.note.method": { zh: "口径：收入含买家支付运费；商品成本取自商品资料（变体成本优先）；费用来自平台结算同步（platform_fee_records），多币种费用不参与基准币汇总、单列展示。", en: "Revenue includes buyer-paid shipping. Product cost comes from product data (variant cost first). Fees come from settlement sync (platform_fee_records); fees in other currencies are excluded from base-currency totals and shown separately." },
