// ---- 运行期补充字典（2026-11-17 货代/物流改造）----
// 三个模块文件由各自的改造者维护，本文件由主会话统一接线，避免并发编辑冲突。
// 优先级：上面全局字典 > EXTRA_*（撞 key 时模块词条被忽略，这是有意为之）
import { EXTRA_FW } from "./extra.fw";
import { EXTRA_LG } from "./extra.lg";
import { EXTRA_SHP } from "./extra.shp";
import { EXTRA_PORTAL } from "./extra.portal";
import { EXTRA_BILL } from "./extra.bill";

const EXTRA: Record<string, { zh: string; en: string }> = {
  ...EXTRA_FW,
  ...EXTRA_LG,
  ...EXTRA_SHP,
  ...EXTRA_PORTAL,
  ...EXTRA_BILL,
};

export type TranslationKey = keyof typeof translations;

// 翻译函数：根据 key 和语言返回文案，支持 {var} 插值


// 动态值翻译：值为字典 key（预置/种子数据存的 log.xxx 等）时按语言翻译，否则原样返回（保护真实用户数据）
export function tIfKey(value: string | null | undefined, lang: Lang, vars?: Record<string, string | number>): string {
  if (!value) return "";
  const entry = (translations as Record<string, { zh: string; en: string }>)[value] ?? EXTRA[value];
  if (!entry) return value;
  return translate(value, lang, vars);
}

export function translate(key: string, lang: Lang, vars?: Record<string, string | number>): string {
  const entry = (translations as Record<string, { zh: string; en: string }>)[key] ?? EXTRA[key];
  let text = entry ? (entry[lang] ?? entry.zh ?? key) : key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      text = text.replaceAll(`{${k}}`, String(v));
    }
  }
  return text;
}